import React, {useState} from 'react'
import './App.css';
import {BrowserRouter as Router, Switch, Route, Redirect, matchPath} from "react-router-dom";
import professorList from './json/professorsList.json'
//Pages
import Home from './pages/Home.js'
import Professor from "./pages/Professor";
import useProfessor from "./hooks/useProfessor";


//hooks
function App() {

    return (
        <Router>
            <Switch>
                <Route path='/' exact component={() => <Home professorList={professorList} onChangeProfessor={setProfessor} isHome={true}/>}/>
                <Route path="/professors/:endpoint" exact component={() => <Professor isHome={false} professorList={professorList} onChangeProfessor={setProfessor} />} />
            </Switch>
        </Router>

);
}

export default App;
